import{_ as e,o as t,c as r,a4 as o}from"./chunks/framework.9tZL7ZIQ.js";const p=JSON.parse('{"title":"1966年 核心总结","description":"","frontmatter":{},"headers":[],"relativePath":"01_letters/1966年/核心总结.md","filePath":"01_letters/1966年/核心总结.md"}'),l={name:"01_letters/1966年/核心总结.md"};function n(i,a,s,_,h,d){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="_1966年-核心总结" tabindex="-1">1966年 核心总结 <a class="header-anchor" href="#_1966年-核心总结" aria-label="Permalink to &quot;1966年 核心总结&quot;">​</a></h1><h2 id="年度业绩" tabindex="-1">年度业绩 <a class="header-anchor" href="#年度业绩" aria-label="Permalink to &quot;年度业绩&quot;">​</a></h2><p>1966年，道琼斯指数大幅下跌15.6%，市场一片惨淡。然而，巴菲特合伙企业逆势上涨20.4%，将领先优势扩大至36个百分点，创造了又一次令人印象深刻的相对收益。合伙企业净资产从约2600万美元大幅增长至4364万美元，充分展示了其在熊市中的防御能力与阿尔法来源的独立性。</p><h2 id="重要事件" tabindex="-1">重要事件 <a class="header-anchor" href="#重要事件" aria-label="Permalink to &quot;重要事件&quot;">​</a></h2><p>1966年是巴菲特投资生涯中具有里程碑意义的一年。他在这一年正式宣告：合伙企业不再接受新的有限合伙人。这一决定反映了他对管理规模与超额收益之间关系的深刻思考——随着资金规模不断扩大，许多原本有效的投资策略会受到流动性与冲击成本的双重约束。巴菲特选择主动控制规模，以保护现有合伙人的长期利益。</p><p>与此同时，巴菲特在信中对合伙人坦诚表达了未来可能面临更大挑战的看法。他明确表示，随着合伙企业规模的增长，维持过去的高超额收益将愈发困难，并警告合伙人不应对未来收益率抱有不切实际的预期。</p><h2 id="投资理念" tabindex="-1">投资理念 <a class="header-anchor" href="#投资理念" aria-label="Permalink to &quot;投资理念&quot;">​</a></h2><p>巴菲特重申了他的核心原则：投资的关键不在于预测市场走势，而在于对企业价值的独立判断。他指出，牛市中的激进与熊市中的恐慌，都是投资者的大敌；真正的超额收益来自于&quot;别人恐惧时贪婪&quot;的逆向决策。他进一步强调，合伙企业的目标不是短期跑赢指数，而是通过长期积累实现资产的实质性增值。</p><h2 id="关键人物" tabindex="-1">关键人物 <a class="header-anchor" href="#关键人物" aria-label="Permalink to &quot;关键人物&quot;">​</a></h2><p>这一时期，汤姆·纳普（Tom Knapp）等早期核心合伙人继续发挥重要作用。与此同时，巴菲特与芒格（Charles Munger）的友谊与思想交流日益深入。芒格作为巴菲特最重要的思想伙伴，其关于优质企业价值投资的理念正在潜移默化地影响巴菲特的投资进化方向。</p>',10)])])}const u=e(l,[["render",n]]);export{p as __pageData,u as default};
